settings.custom_liquid:
{% if collection.description != blank %}
  <div style="padding:12px 20px 0;">
    <div style="max-width:1180px;margin:0 auto;text-align:center;font-size:18px;line-height:1.5;color:#222;">
      {{ collection.description | replace: '<p>', '<p style="margin:0;">' }}
    </div>
  </div>
{% endif %}

{% if collection.handle == 'hundesport-hosen' %}
{% assign pants = all_products['iq-dogsport-hose-unisex'] %}
{% assign en = false %}{% if request.locale.iso_code == 'en' %}{% assign en = true %}{% endif %}
{% if pants != blank %}
{% assign pants_video = pants.media | where: 'media_type', 'video' | first %}
{% if pants_video != blank %}
<div class="iq-pants-block"><div class="iq-pants-video-wrap">
<p class="iq-pants-kicker">{% if en %}See it in action{% else %}Im Einsatz{% endif %}</p>
<h2>{% if en %}Your trousers in training.{% else %}Deine Hose im Training.{% endif %}</h2>
{{ pants_video | video_tag: image_size: '1000x', controls: true, autoplay: false, loop: false, preload: 'none', class: 'iq-pants-video' }}
</div></div>
{% elsif request.design_mode %}<p>Für diese Hose ist noch kein Shopify-Produktvideo hinterlegt.</p>{% endif %}
<style>.iq-pants-block{max-width:1180px;margin:0 auto;padding:40px 24px;color:#171717;font:400 16px/1.55 Archivo,sans-serif}.iq-pants-block *{box-sizing:border-box}.iq-pants-grid{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}.iq-pants-block h2{font:800 italic clamp(28px,3vw,42px)/1.12 Montserrat,sans-serif;text-transform:uppercase;margin:0 0 20px}.iq-pants-block h3{font:700 20px/1.3 Archivo,sans-serif;margin:0 0 8px}.iq-pants-block p{margin:0 0 18px}.iq-pants-block .iq-pants-kicker{font:700 12px/1.4 Archivo,sans-serif;letter-spacing:.1em;text-transform:uppercase;color:#A51D1B;margin-bottom:12px}.iq-pants-photo{display:block;width:100%;height:auto}.iq-pants-product{height:480px;object-fit:contain}.iq-pants-block ul{padding-left:20px;margin:20px 0}.iq-pants-block li{margin:8px 0}.iq-pants-block .iq-pants-price{font:700 24px/1.3 Archivo,sans-serif;margin:24px 0 12px}.iq-pants-cta{display:inline-flex;align-items:center;justify-content:center;background:#171717;color:#fff!important;padding:14px 24px;min-height:48px;text-decoration:none;font-weight:700}.iq-pants-cta:focus-visible{outline:3px solid #A51D1B;outline-offset:4px}.iq-pants-block .iq-pants-small{font-size:13px;margin-top:10px}.iq-pants-block a:not(.iq-pants-cta){color:inherit;text-underline-offset:4px}.iq-pants-detail{border-top:1px solid #DCDBD7}.iq-pants-detail article+article{border-top:1px solid #DCDBD7;margin-top:22px;padding-top:22px}.iq-pants-video{display:block;width:100%;max-height:640px;background:#171717;object-fit:contain;height:auto}.iq-pants-video-wrap{max-width:850px;margin:auto}.iq-pants-video-wrap h2{font-size:clamp(26px,3vw,36px)}@media(max-width:749px){.iq-pants-block{padding:28px 20px;font-size:15px}.iq-pants-grid{grid-template-columns:1fr;gap:24px}.iq-pants-product{height:330px}.iq-pants-block h2{font-size:28px}.iq-pants-cta{width:100%}.iq-pants-video{max-height:70vh}}</style>
{% endif %}
{% endif %}

{% if collection.handle == 'hundesport-hosen' %}
{% assign pants = all_products['iq-dogsport-hose-unisex'] %}
{% assign en = false %}{% if request.locale.iso_code == 'en' %}{% assign en = true %}{% endif %}
{% if pants != blank %}
<div class="iq-pants-block iq-pants-detail"><div class="iq-pants-grid">
<img class="iq-pants-photo" src="https://cdn.shopify.com/s/files/1/0625/2806/1688/files/hundesport-hose-futtertasche-iq-dogsport.jpg?v=1775315587&width=900" width="900" height="900" style="aspect-ratio:1;object-fit:contain" loading="lazy" alt="{% if en %}Removable treat pouch on the IQ Trainer Pants{% else %}Herausnehmbare Futtertasche der IQ Trainer Pants{% endif %}">
<div><p class="iq-pants-kicker">{% if en %}Details that make a difference{% else %}Durchdachte Details{% endif %}</p>
<h2>{% if en %}Ready to reward.{% else %}Bereit zum Belohnen.{% endif %}</h2>
<article><h3>{% if en %}Remove. Rinse. Keep training.{% else %}Rausnehmen. Abwaschen. Weitertrainieren.{% endif %}</h3><p>{% if en %}The integrated treat pouches are coated and removable, making them easy to clean after training.{% else %}Die integrierten Futtertaschen sind beschichtet und herausnehmbar. So lassen sie sich nach dem Training einfach reinigen.{% endif %}</p></article>
<article><h3>{% if en %}Room for your reward toy{% else %}Platz für Dein Belohnungsspielzeug{% endif %}</h3><p>{% if en %}The concealed rear pocket holds your toy or bite pillow.{% else %}In der versteckten Rückentasche finden Spielzeug oder Beißkissen Platz.{% endif %}</p></article>

<article><h3>{% if en %}Need more space?{% else %}Du brauchst mehr Platz?{% endif %}</h3><p>{% if en %}Add the optional <a href="{{ routes.root_url }}{% unless routes.root_url == '/' %}/{% endunless %}products/iq-modulare-futtertasche">IQ modular treat pouch</a>. Sold separately.{% else %}Die optionale <a href="{{ routes.root_url }}{% unless routes.root_url == '/' %}/{% endunless %}products/iq-modulare-futtertasche">IQ Modulare Futtertasche</a> lässt sich zusätzlich einhängen. Separat erhältlich.{% endif %}</p></article>
</div></div></div>
<style>.iq-pants-block{max-width:1180px;margin:0 auto;padding:40px 24px;color:#171717;font:400 16px/1.55 Archivo,sans-serif}.iq-pants-block *{box-sizing:border-box}.iq-pants-grid{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}.iq-pants-block h2{font:800 italic clamp(28px,3vw,42px)/1.12 Montserrat,sans-serif;text-transform:uppercase;margin:0 0 20px}.iq-pants-block h3{font:700 20px/1.3 Archivo,sans-serif;margin:0 0 8px}.iq-pants-block p{margin:0 0 18px}.iq-pants-block .iq-pants-kicker{font:700 12px/1.4 Archivo,sans-serif;letter-spacing:.1em;text-transform:uppercase;color:#A51D1B;margin-bottom:12px}.iq-pants-photo{display:block;width:100%;height:auto}.iq-pants-product{height:480px;object-fit:contain}.iq-pants-block ul{padding-left:20px;margin:20px 0}.iq-pants-block li{margin:8px 0}.iq-pants-block .iq-pants-price{font:700 24px/1.3 Archivo,sans-serif;margin:24px 0 12px}.iq-pants-cta{display:inline-flex;align-items:center;justify-content:center;background:#171717;color:#fff!important;padding:14px 24px;min-height:48px;text-decoration:none;font-weight:700}.iq-pants-cta:focus-visible{outline:3px solid #A51D1B;outline-offset:4px}.iq-pants-block .iq-pants-small{font-size:13px;margin-top:10px}.iq-pants-block a:not(.iq-pants-cta){color:inherit;text-underline-offset:4px}.iq-pants-detail{border-top:1px solid #DCDBD7}.iq-pants-detail article+article{border-top:1px solid #DCDBD7;margin-top:22px;padding-top:22px}.iq-pants-video{display:block;width:100%;max-height:640px;background:#171717;object-fit:contain;height:auto}.iq-pants-video-wrap{max-width:850px;margin:auto}.iq-pants-video-wrap h2{font-size:clamp(26px,3vw,36px)}@media(max-width:749px){.iq-pants-block{padding:28px 20px;font-size:15px}.iq-pants-grid{grid-template-columns:1fr;gap:24px}.iq-pants-product{height:330px}.iq-pants-block h2{font-size:28px}.iq-pants-cta{width:100%}.iq-pants-video{max-height:70vh}}</style>
{% endif %}
{% endif %}

{% if collection.description != blank %}
  {% assign description_parts = collection.description | split: '</p>' %}
  {% assign rest_description = description_parts | slice: 1, 999 | join: '</p>' %}

  {% if rest_description != blank %}
    <div class="page-width collection-seo-text">
      {{ rest_description }}
    </div>
  {% endif %}
{% endif %}
